// MaxTokensPerAccount, never one keep names and never one that signed in a
// computer by phone or a web session still listed (via_token): deleting it
// would detach those from the cascade that revokes them with it
// (RevokeTokenCascade), so the next least recently used token goes instead.
func trimTokens(tx *sql.Tx, name string, keep []string) error {
	var n int
	if err := tx.QueryRow(`SELECT count(*) FROM tokens WHERE username = ?`, name).Scan(&n); err != nil {
		return err
	}
	if n <= MaxTokensPerAccount {
		return nil
	}
	rows, err := tx.Query(`SELECT id FROM tokens AS t WHERE username = ?
		AND NOT EXISTS (SELECT 1 FROM tokens AS d WHERE d.username = t.username AND d.via_token = t.id
			AND (d.sign_in_method = ? OR d.kind = ?))
		ORDER BY coalesce(last_used_at, created_at), id`, name, SignInMethodPhone, TokenKindWeb)
	if err != nil {
		return err
	}
	ids, err := scanStrings(rows)
	if err != nil {
		return err
	}
	for _, id := range ids {
		if n <= MaxTokensPerAccount {
			break
		}
		if slices.Contains(keep, id) {
			continue
		}
		if _, err := tx.Exec(`DELETE FROM tokens WHERE id = ?`, id); err != nil {
			return err
		}
		n--
	}
	return nil
}

func (db *DB) MintToken(name, label string) (raw string, err error) {
	return db.MintTokenCreatedAt(name, label, secs(time.Now()))
}

// MintTokenCreatedAt is MintToken recording createdAt as the token's
// sign-in time.
func (db *DB) MintTokenCreatedAt(name, label string, createdAt time.Time) (raw string, err error) {
	err = db.write(func(tx *sql.Tx) error {
		if _, err := scanUser(tx, name); err != nil {
			return err
		}
		raw, err = insertTokenCreatedAt(tx, name, label, createdAt)
		return err
	})
	return
}

// MintTokenIfPasswordIs mints a token only if the account's password hash
// still equals the one the caller authenticated against moments ago, and the
// second factor (if enrolled) accepts code. Login uses it so a password
// change between Authenticate and the mint cannot be raced.
func (db *DB) MintTokenIfPasswordIs(name, label, passwordHash, code string, now time.Time) (raw string, err error) {
	return db.mintIfPasswordIs(name, passwordHash, code, now, func(tx *sql.Tx) (string, error) {
		return insertToken(tx, name, label, now)
	})
}

// mintIfPasswordIs runs mint inside the transaction that checks the
// account's password hash is still passwordHash and its second factor (if
// enrolled) accepts code, the guarded mint every sign-in shares. A sign-in
// leaves the account's unspent invite alone.
func (db *DB) mintIfPasswordIs(name, passwordHash, code string, now time.Time, mint func(tx *sql.Tx) (string, error)) (raw string, err error) {
	err = db.write(func(tx *sql.Tx) error {
		u, err := scanUser(tx, name)
		if err != nil {
			return err
		}
		if u.PasswordHash != passwordHash {
			return ErrBadCredentials
		}
		if err := db.checkSecondFactor(tx, &u, code, now); err != nil {
			return err
		}
		raw, err = mint(tx)
		return err
	})
	return
}

// UserByToken resolves a bearer token, never a web session: a web row holds
// a different hash of its value (WebSessionHash), and a row of kind 'web' is
// refused whatever it holds. The token's last-used stamp moves at
// most once an hour, so a busy client does not write on every request. The
// token row and the user are read together in one transaction. client is
// this request's X-HyperDrop-Client header, parsed; a non-empty value that
// differs from the row is written onto the token.
func (db *DB) UserByToken(raw string, client ClientInfo) (User, error) {
	h := TokenHash(raw)
	var u User
	var lastUsed sql.NullInt64
	var storedVersion string
	err := db.read(func(tx *sql.Tx) error {
		var name string
		if err := tx.QueryRow(`SELECT username, last_used_at, client_version FROM tokens WHERE sha256 = ? AND kind IS NOT ?`, h, TokenKindWeb).
			Scan(&name, &lastUsed, &storedVersion); err != nil {
			return err
		}
		var err error
		u, err = scanUser(tx, name)
		return err
	})
	if errors.Is(err, sql.ErrNoRows) || errors.Is(err, ErrUserNotFound) {
		return User{}, ErrBadCredentials
	}
	if err != nil {
		return User{}, err
	}
	now := time.Now()
	if !u.Active(now) {
		return User{}, ErrInactive
	}
	use := useAt(now, lastUsed, storedVersion, client)
	if use.due() {
		// Best-effort bookkeeping, in one write transaction.
		_ = db.write(func(tx *sql.Tx) error { return use.record(tx, h) })
	}
	patchToken(&u, h, use.apply)
	return u, nil
}

// tokenUse is what a lookup records of a token's use, UserByToken's and
// UserByWebSession's alike: the last-used stamp, moved at most once per
// lastUsedGranularity, and the client header when it names another version
// than the row holds.
type tokenUse struct {
	stamp     bool
	at        int64
	newClient bool
	client    ClientInfo
}

// useAt is the use a lookup at now records of a row last used at lastUsed
// from storedVersion, by a request that named client.
func useAt(now time.Time, lastUsed sql.NullInt64, storedVersion string, client ClientInfo) tokenUse {
	return tokenUse{
		stamp:     !lastUsed.Valid || now.Sub(fromNS(lastUsed.Int64)) > lastUsedGranularity,
		at:        toNS(secs(now)),
		newClient: !client.Empty() && client.Version != storedVersion,
		client:    client,
	}
}

// due reports whether the use has anything to write.
func (t tokenUse) due() bool { return t.stamp || t.newClient }

// record writes the use onto the row whose hash is hash. Runs inside tx.
func (t tokenUse) record(tx *sql.Tx, hash string) error {
	if t.stamp {
		if _, err := tx.Exec(`UPDATE tokens SET last_used_at = ? WHERE sha256 = ?`, t.at, hash); err != nil {
			return err
		}
	}
	if t.newClient {
		if _, err := tx.Exec(`UPDATE tokens SET client_version = ?, client_platform = ? WHERE sha256 = ?`,
			t.client.Version, t.client.Platform, hash); err != nil {
			return err
		}
	}
	return nil
}

// apply is record on a row already read.
func (t tokenUse) apply(tok *Token) {
	if t.stamp {
		tok.LastUsedAt = fromNS(t.at)
	}
	if t.newClient {
		tok.ClientVersion, tok.ClientPlatform = t.client.Version, t.client.Platform
	}
}

// patchToken runs change on u's token row whose hash is hash and answers
// the row, zero when u holds none.
func patchToken(u *User, hash string, change func(*Token)) Token {
	for i := range u.Tokens {
		if u.Tokens[i].SHA256 == hash {
			change(&u.Tokens[i])
			return u.Tokens[i]
		}
	}
	return Token{}
}

// ErrNoSuchToken is a revoke naming no token of the account.
var ErrNoSuchToken = &namedError{msg: "no such device token", is: ErrNotFound}

// RevokeToken deletes one of the account's tokens, answering ErrNoSuchToken
// when tokenID names none of them, another account's included.
func (db *DB) RevokeToken(name, tokenID string) error {
	return db.write(func(tx *sql.Tx) error {
		if _, err := scanUser(tx, name); err != nil {
			return err
		}
		res, err := tx.Exec(`DELETE FROM tokens WHERE username = ? AND id = ?`, name, tokenID)
		if err != nil {
			return err
		}
		if n, _ := res.RowsAffected(); n == 0 {
			return ErrNoSuchToken
		}
		return nil
	})
}

// RevokeTokenCascade deletes one of the account's tokens together with the
// tokens it approved (via_token), followed transitively, in one transaction,
// and answers every id it deleted, tokenID first. A dependent signed in by
// phone (sign_in_method 'phone') or a web session always goes, and the walk
// continues through it. Any other dependent, a phone linked through Sign In
// a Phone, goes only when its id is in alsoLinked, and the walk continues
// through it only then; an id in alsoLinked that the walk does not reach is
// ignored. Every id is collected before any row is deleted, because a delete
// clears via_token on the rows it approved. The walk reads only the
// account's own tokens and visits each at most once, so a via_token cycle
// ends it. ErrNoSuchToken when tokenID names none of the account's tokens,
// another account's included.
func (db *DB) RevokeTokenCascade(name, tokenID string, alsoLinked []string) (revoked []string, err error) {
	err = db.write(func(tx *sql.Tx) error {
		if _, err := scanUser(tx, name); err != nil {
			return err
		}
		var n int
		if err := tx.QueryRow(`SELECT count(*) FROM tokens WHERE username = ? AND id = ?`, name, tokenID).Scan(&n); err != nil {
			return err
		}
		if n == 0 {
			return ErrNoSuchToken
		}
		listed := make(map[string]bool, len(alsoLinked))
		for _, id := range alsoLinked {
			listed[id] = true
		}
		seen := map[string]bool{tokenID: true}
		ids := []string{tokenID}
		for i := 0; i < len(ids); i++ {
			rows, err := tx.Query(`SELECT id, coalesce(kind, ''), coalesce(sign_in_method, '') FROM tokens
				WHERE username = ? AND via_token = ?`, name, ids[i])
			if err != nil {
				return err
			}
			var id, kind, method string
			if err := eachRow(rows, func() error {
				if err := rows.Scan(&id, &kind, &method); err != nil {
					return err
				}
				if seen[id] {
					return nil
				}
				seen[id] = true
				if method == SignInMethodPhone || kind == TokenKindWeb || listed[id] {
					ids = append(ids, id)
				}
				return nil
			}); err != nil {
				return err
			}
		}
		for _, id := range ids {
			if _, err := tx.Exec(`DELETE FROM tokens WHERE username = ? AND id = ?`, name, id); err != nil {
				return err
			}
		}
		revoked = ids
		return nil
	})
	if err != nil {
		return nil, err
	}
	return revoked, nil
}

// TokenLive reports whether tokenID is still one of account name's tokens
// at now, and its kind: a device token while its row exists, a web session
// while it is also inside its idle and absolute limits, and either only
// while the account is active. One lookup by the tokens table's key; it
// writes nothing.
func (db *DB) TokenLive(name, tokenID string, now time.Time) (kind string, live bool, err error) {
	err = db.read(func(tx *sql.Tx) error {
		var idle, expires, accountExpires sql.NullInt64
		var disabled bool
		err := tx.QueryRow(`SELECT coalesce(t.kind, ''), t.idle_until, t.expires_at, u.disabled, u.account_expires_at
			FROM tokens t JOIN users u ON u.username = t.username WHERE t.id = ? AND t.username = ?`, tokenID, name).
			Scan(&kind, &idle, &expires, &disabled, &accountExpires)
		if errors.Is(err, sql.ErrNoRows) {
			return nil
		}
		if err != nil {
			return err
		}
		u := User{Disabled: disabled, AccountExpiresAt: fromNSPtr(accountExpires)}
		live = u.Active(now)
		if kind == TokenKindWeb {
			live = live && idle.Valid && expires.Valid && now.Before(fromNS(idle.Int64)) && now.Before(fromNS(expires.Int64))
		}
		return nil
	})
	if err != nil || !live {
		return "", false, err
	}
	return kind, true, nil
}

// BcryptCost is the work factor of every password hash the server makes:
// account passwords here, share passwords in the api package. Tests lower
// it; nothing on a request path writes it.
var BcryptCost = bcrypt.DefaultCost
